do $$
declare room text; actor uuid; visit uuid; signal text; wrong_signal text; code text; first_start timestamptz; reply jsonb; before_reply jsonb; blocked boolean; result_one jsonb:='{"schema_version": 2, "room_id": "beliefs", "team_id": 1, "started_at": "1970-01-01T00:00:01.000Z", "finished_at": "1970-01-01T00:00:05.000Z", "duration_ms": 4000, "completion_mode": "normal", "summary": {"keywords": []}, "interaction_count": 7, "remaining_keywords": [], "added_keywords": [], "discarded_keywords": ["실력", "자유", "연봉", "명예", "봉사", "성장", "안정"], "discarded_initial_keywords": ["실력", "자유", "연봉", "명예", "봉사", "성장", "안정"], "all_added_keywords": [], "final_keywords": [], "history": [{"sequence": 1, "type": "discard", "label_id": "initial-0", "text": "실력", "source": "initial", "at": "1970-01-01T00:00:02.000Z", "elapsed_ms": 1000}, {"sequence": 2, "type": "discard", "label_id": "initial-1", "text": "자유", "source": "initial", "at": "1970-01-01T00:00:02.100Z", "elapsed_ms": 1100}, {"sequence": 3, "type": "discard", "label_id": "initial-2", "text": "연봉", "source": "initial", "at": "1970-01-01T00:00:02.200Z", "elapsed_ms": 1200}, {"sequence": 4, "type": "discard", "label_id": "initial-3", "text": "명예", "source": "initial", "at": "1970-01-01T00:00:02.300Z", "elapsed_ms": 1300}, {"sequence": 5, "type": "discard", "label_id": "initial-4", "text": "봉사", "source": "initial", "at": "1970-01-01T00:00:02.400Z", "elapsed_ms": 1400}, {"sequence": 6, "type": "discard", "label_id": "initial-5", "text": "성장", "source": "initial", "at": "1970-01-01T00:00:02.500Z", "elapsed_ms": 1500}, {"sequence": 7, "type": "discard", "label_id": "initial-6", "text": "안정", "source": "initial", "at": "1970-01-01T00:00:02.600Z", "elapsed_ms": 1600}]}'::jsonb; result_two jsonb:='{"schema_version": 1, "room_id": "self-knowledge", "team_id": 2, "revision": 6, "started_at": "1970-01-01T00:00:01.000Z", "finished_at": "1970-01-01T00:00:03.000Z", "updated_at": "1970-01-01T00:00:03.000Z", "duration_ms": 2000, "language": "ko", "answers": {"outfit": ["discover", "explore"], "strength": ["observe", "craft"], "aura": ["people", "tools"]}, "result_code": "v1.000000", "selections": [{"chest_id": "outfit", "scene_id": "birthday-before", "option_id": "discover", "label": "알아내기", "action": "좋아하는 케이크 찾아보기", "treasure": {"name": "발견의 돋보기", "description": "궁금한 것을 그냥 지나치지 않고 알아가는 일에 마음이 향했어요. 작은 단서를 찾아보는 시간이 새로운 가능성을 열어줄 수 있어요."}}, {"chest_id": "outfit", "scene_id": "birthday-after", "option_id": "explore", "label": "탐험하기", "action": "파티룸 앞에 뭐가 있는지 둘러보기", "treasure": {"name": "새길의 나침반", "description": "익숙한 곳을 벗어나 새로운 장소를 직접 만나보고 싶었군요. 낯선 길에서 마주치는 작은 발견이 다음 호기심으로 이어질 수 있어요."}}, {"chest_id": "strength", "scene_id": "tidy-before", "option_id": "observe", "label": "관찰력", "action": "소파 틈 물건 찾기", "treasure": {"name": "세심함의 렌즈", "description": "다른 사람이 지나친 작은 차이를 살피는 행동을 골랐어요. 평소에도 이런 순간이 있었다면 세심한 관찰이 나의 강점으로 쓰였을지 떠올려 보세요."}}, {"chest_id": "strength", "scene_id": "tidy-after", "option_id": "craft", "label": "손재주", "action": "종이를 잘라 수납 칸 만들기", "treasure": {"name": "섬세함의 공구", "description": "손으로 작은 부분을 다듬고 고치는 행동을 골랐어요. 직접 만지고 손보며 무언가를 완성했던 순간에 나의 섬세함이 어떻게 드러났는지 돌아보세요."}}, {"chest_id": "aura", "scene_id": "break-before", "option_id": "people", "label": "사람과 마음", "action": "친구랑 대화하기", "treasure": {"name": "마음의 진주", "description": "친구와 편하게 이야기를 나누는 시간에 마음이 머물렀어요. 소소한 일상을 주고받고 함께 웃는 시간이 나에게 즐거움을 줄 수 있어요."}}, {"chest_id": "aura", "scene_id": "break-after", "option_id": "tools", "label": "기술과 도구", "action": "새로 산 기기의 기능 둘러보기", "treasure": {"name": "원리의 톱니", "description": "새로 산 기기의 기능을 살펴보는 활동에 마음이 향했어요. 메뉴를 눌러보고 사용법을 알아가는 과정에서 소소한 재미를 느낄 수 있어요."}}], "selected_actions": ["좋아하는 케이크 찾아보기", "파티룸 앞에 뭐가 있는지 둘러보기", "소파 틈 물건 찾기", "종이를 잘라 수납 칸 만들기", "친구랑 대화하기", "새로 산 기기의 기능 둘러보기"], "summary": {"keywords": ["알아내기", "탐험하기", "관찰력", "손재주", "사람과 마음", "기술과 도구"], "treasures": ["발견의 돋보기", "새길의 나침반", "세심함의 렌즈", "섬세함의 공구", "마음의 진주", "원리의 톱니"]}, "seals_count": 6, "seal_placements": {"outfit-0": 0, "outfit-1": 1, "strength-0": 2, "strength-1": 3, "aura-0": 4, "aura-1": 5}, "history": [{"sequence": 1, "chest_id": "outfit", "scene_id": "birthday-before", "option_id": "discover", "at": "1970-01-01T00:00:01.100Z", "elapsed_ms": 100}, {"sequence": 2, "chest_id": "outfit", "scene_id": "birthday-after", "option_id": "explore", "at": "1970-01-01T00:00:01.200Z", "elapsed_ms": 200}, {"sequence": 3, "chest_id": "strength", "scene_id": "tidy-before", "option_id": "observe", "at": "1970-01-01T00:00:01.300Z", "elapsed_ms": 300}, {"sequence": 4, "chest_id": "strength", "scene_id": "tidy-after", "option_id": "craft", "at": "1970-01-01T00:00:01.400Z", "elapsed_ms": 400}, {"sequence": 5, "chest_id": "aura", "scene_id": "break-before", "option_id": "people", "at": "1970-01-01T00:00:01.500Z", "elapsed_ms": 500}, {"sequence": 6, "chest_id": "aura", "scene_id": "break-after", "option_id": "tools", "at": "1970-01-01T00:00:01.600Z", "elapsed_ms": 600}]}'::jsonb; result_edit jsonb:='{"schema_version": 1, "room_id": "self-knowledge", "team_id": 2, "revision": 7, "started_at": "1970-01-01T00:00:01.000Z", "finished_at": "1970-01-01T00:00:03.000Z", "updated_at": "1970-01-01T00:00:03.100Z", "duration_ms": 2000, "language": "ko", "answers": {"outfit": ["create", "explore"], "strength": ["observe", "craft"], "aura": ["people", "tools"]}, "result_code": "v1.100000", "selections": [{"chest_id": "outfit", "scene_id": "birthday-before", "option_id": "create", "label": "창작하기", "action": "축하 카드 그리기", "treasure": {"name": "상상의 팔레트", "description": "떠오른 생각을 나만의 그림과 이야기로 펼치는 역할을 골랐어요. 아직 없던 것을 상상해 보는 시간이 나다운 표현의 시작이 될 수 있어요."}}, {"chest_id": "outfit", "scene_id": "birthday-after", "option_id": "explore", "label": "탐험하기", "action": "파티룸 앞에 뭐가 있는지 둘러보기", "treasure": {"name": "새길의 나침반", "description": "익숙한 곳을 벗어나 새로운 장소를 직접 만나보고 싶었군요. 낯선 길에서 마주치는 작은 발견이 다음 호기심으로 이어질 수 있어요."}}, {"chest_id": "strength", "scene_id": "tidy-before", "option_id": "observe", "label": "관찰력", "action": "소파 틈 물건 찾기", "treasure": {"name": "세심함의 렌즈", "description": "다른 사람이 지나친 작은 차이를 살피는 행동을 골랐어요. 평소에도 이런 순간이 있었다면 세심한 관찰이 나의 강점으로 쓰였을지 떠올려 보세요."}}, {"chest_id": "strength", "scene_id": "tidy-after", "option_id": "craft", "label": "손재주", "action": "종이를 잘라 수납 칸 만들기", "treasure": {"name": "섬세함의 공구", "description": "손으로 작은 부분을 다듬고 고치는 행동을 골랐어요. 직접 만지고 손보며 무언가를 완성했던 순간에 나의 섬세함이 어떻게 드러났는지 돌아보세요."}}, {"chest_id": "aura", "scene_id": "break-before", "option_id": "people", "label": "사람과 마음", "action": "친구랑 대화하기", "treasure": {"name": "마음의 진주", "description": "친구와 편하게 이야기를 나누는 시간에 마음이 머물렀어요. 소소한 일상을 주고받고 함께 웃는 시간이 나에게 즐거움을 줄 수 있어요."}}, {"chest_id": "aura", "scene_id": "break-after", "option_id": "tools", "label": "기술과 도구", "action": "새로 산 기기의 기능 둘러보기", "treasure": {"name": "원리의 톱니", "description": "새로 산 기기의 기능을 살펴보는 활동에 마음이 향했어요. 메뉴를 눌러보고 사용법을 알아가는 과정에서 소소한 재미를 느낄 수 있어요."}}], "selected_actions": ["축하 카드 그리기", "파티룸 앞에 뭐가 있는지 둘러보기", "소파 틈 물건 찾기", "종이를 잘라 수납 칸 만들기", "친구랑 대화하기", "새로 산 기기의 기능 둘러보기"], "summary": {"keywords": ["창작하기", "탐험하기", "관찰력", "손재주", "사람과 마음", "기술과 도구"], "treasures": ["상상의 팔레트", "새길의 나침반", "세심함의 렌즈", "섬세함의 공구", "마음의 진주", "원리의 톱니"]}, "seals_count": 6, "seal_placements": {"outfit-0": 0, "outfit-1": 1, "strength-0": 2, "strength-1": 3, "aura-0": 4, "aura-1": 5}, "history": [{"sequence": 1, "chest_id": "outfit", "scene_id": "birthday-before", "option_id": "discover", "at": "1970-01-01T00:00:01.100Z", "elapsed_ms": 100}, {"sequence": 2, "chest_id": "outfit", "scene_id": "birthday-after", "option_id": "explore", "at": "1970-01-01T00:00:01.200Z", "elapsed_ms": 200}, {"sequence": 3, "chest_id": "strength", "scene_id": "tidy-before", "option_id": "observe", "at": "1970-01-01T00:00:01.300Z", "elapsed_ms": 300}, {"sequence": 4, "chest_id": "strength", "scene_id": "tidy-after", "option_id": "craft", "at": "1970-01-01T00:00:01.400Z", "elapsed_ms": 400}, {"sequence": 5, "chest_id": "aura", "scene_id": "break-before", "option_id": "people", "at": "1970-01-01T00:00:01.500Z", "elapsed_ms": 500}, {"sequence": 6, "chest_id": "aura", "scene_id": "break-after", "option_id": "tools", "at": "1970-01-01T00:00:01.600Z", "elapsed_ms": 600}, {"sequence": 7, "chest_id": "outfit", "scene_id": "birthday-before", "option_id": "create", "at": "1970-01-01T00:00:03.100Z", "elapsed_ms": 2100}]}'::jsonb;
begin
 foreach room in array array['beliefs','self-knowledge'] loop
  actor:=gen_random_uuid();
  select signal_key,qr_code into signal,code from public.room_booths where room_id=room for no key update;
  select signal_key into wrong_signal from public.room_booths where room_id='conflict';
  delete from public.booth_selections where room_id=room;
  insert into auth.users(id,aud,role,is_anonymous,created_at,updated_at)values(actor,'authenticated','authenticated',true,now(),now());
  insert into public.visitor_profiles(id,name,student_id,department,nickname)values(actor,'선택 연결 점검',left(actor::text,30),'검증','시작 종료 점검');
  perform set_config('request.jwt.claim.sub',actor::text,true);
  perform set_config('request.jwt.claims',jsonb_build_object('sub',actor,'role','authenticated')::text,true);
  reply:=public.enter_room_developer(room,code,gen_random_uuid());visit:=(reply->>'visit_id')::uuid;
  if(select experience_started_at from public.room_visits where id=visit)is not null then raise exception 'ASSERT QR alone not start';end if;
  blocked:=false;begin perform public.record_station_start(room,wrong_signal,visit,now());exception when insufficient_privilege then blocked:=true;end;
  if not blocked then raise exception 'ASSERT key isolation';end if;
  if room='beliefs' then reply:=public.beliefs_queue_start(signal,visit,now());else reply:=public.treasure_station_start(signal,visit,now());end if;
  first_start:=(reply->>'experience_started_at')::timestamptz;
  if first_start is null or (select experience_started_at from public.room_visits where id=visit)<>first_start then raise exception 'ASSERT actual start';end if;
  reply:=public.record_station_start(room,signal,visit,now()+interval '1 second');
  if(reply->>'experience_started_at')::timestamptz<>first_start then raise exception 'ASSERT start retry';end if;
  if room='beliefs' then reply:=public.beliefs_queue_complete(signal,visit,result_one);else reply:=public.treasure_station_save(signal,visit,result_two);end if;
  if reply->>'status'<>'completed' then raise exception 'ASSERT completion';end if;
  before_reply:=reply;
  reply:=public.record_station_start(room,signal,visit,now()+interval '2 seconds');
  if(reply->>'experience_started_at')::timestamptz<>first_start then raise exception 'ASSERT late start cannot overwrite completed time';end if;
  if room='beliefs' then reply:=public.beliefs_queue_complete(signal,visit,result_one);
  else reply:=public.treasure_station_save(signal,visit,result_two);end if;
  if reply<>before_reply then raise exception 'ASSERT completion retry';end if;
  if (select result from public.room_visits where id=visit) is distinct from (case when room='beliefs' then result_one else result_two end)
   or(select result from public.room_completions where visit_id=visit) is distinct from (case when room='beliefs' then result_one else result_two end) then raise exception 'ASSERT both tables';end if;
  if room='self-knowledge' then
   reply:=public.treasure_station_save(signal,visit,result_edit);
   if reply->>'saved_revision'<>'7' or (select experience_started_at from public.room_visits where id=visit)<>first_start then raise exception 'ASSERT edited results retain start';end if;
  end if;
  reply:=public.enter_room_developer(room,code,gen_random_uuid());visit:=(reply->>'visit_id')::uuid;
  perform public.stop_room_visit(visit);blocked:=false;
  begin perform public.record_station_start(room,signal,visit,now());exception when invalid_parameter_value then if sqlerrm<>'VISIT_STOPPED' then raise;end if;blocked:=true;end;
  if not blocked then raise exception 'ASSERT stopped start rejection';end if;
 end loop;
end $$;
rollback;
select 'PASS: team 1/2 optional start, QR alone not start, scoped key, idempotent start, completion and retries, immutable start, both result tables, team 2 revisions, stopped start rejection. All test data rolled back.' as result;
